/**
 * @param {number} width
 * @param {number} height
 * @return {number}
 */
export default function uniquePaths(width, height) {
  const pascalLine = width + height - 2;
  const pascalLinePosition = Math.min(width, height) - 1;

  return pascalTriangle(pascalLine)[pascalLinePosition];
}

