    this.startVertex = startVertex;
    this.endVertex = endVertex;
    this.weight = weight;
    // A custom key (if provided) is a stable identity that is kept on reverse.
    // Auto-generated keys are recomputed so they always reflect the direction.
    this.customKey = key;
    this.key = key;
