  getKey() {
    if (this.key) {
      return this.key;
    }

    const startVertexKey = this.startVertex.getKey();
    const endVertexKey = this.endVertex.getKey();

    this.key = `${startVertexKey}_${endVertexKey}`;

    return this.key;
